-- PHIẾU KHÁM v2 GỌN (đợt 3, 27/09/2026) — góp ý phòng khám (bác sĩ chính + thư ký
-- y khoa): B1 tiền sử thu gọn thành chip, bấm mới hiện ô · B2 dị ứng thuốc Có/Không,
-- chọn Có mới hiện "Chi tiết" · B3 bảng kết quả CLS gõ tay vào ngăn gập.
-- Sinh bằng scripts/phieu-kham/dung-phieu-v2.py từ v1 (20260924000008) → cùng dữ
-- liệu với src/clinicai/phieu_kham/dinh_nghia/*.json.
--
-- GIỮ NGUYÊN MỌI `ma` của v1; chỉ thêm ô `*_allergy_co` (NT · HMVS · SK) và cặp
-- `pk_allergy_co`/`pk_allergy`, `nk_allergy_co`/`nk_allergy` (PK · NK). Ba thuộc
-- tính mới (`thu_gon`, `hien_khi`, `gap`) chỉ là cách HIỂN THỊ — engine bỏ qua.
--
-- Chỉ thay bản do HỆ THỐNG xuất bản (xuat_ban_boi NULL): phòng khám đã tự xuất bản
-- thì không đè. Bản cũ → RETIRED; phiếu đã mở ghim version cũ
-- (`phieu_kham_luot.version`) vẫn đọc đúng khung cũ. THU_THUAT, SAN_CHAU không đổi.
-- Chạy lại được (khung đã bằng v2 thì không làm gì).

WITH cu AS (
    SELECT d.clinic_id, d.version, d.nhom FROM public.form_definition d
     WHERE d.form_id = 'NT' AND d.trang_thai = 'PUBLISHED'
       AND d.xuat_ban_boi IS NULL
       AND d.khung IS DISTINCT FROM $khung$[{"ma": "HANH_CHINH", "ten": "Hành chính & sinh hiệu", "lien_ket": {"loai": "mang_sang", "truong": ["patient.name", "patient.birth_year", "patient.code", "encounter.date", "vitals.blood_pressure", "vitals.pulse", "vitals.weight", "vitals.height", "vitals.temperature", "vitals.spo2", "vitals.bmi", "vitals.respiratory_rate", "vitals.pain_score"]}, "block": []}, {"ma": "A", "ten": "A. Khám của bác sĩ tư vấn", "block": [{"ma": "nt_a_note", "ten": "Ghi chú bổ sung (nếu cần)", "kieu": "doan_van"}], "lien_ket": {"loai": "mang_sang", "nguon": "doctor-consultation"}}, {"ma": "B", "ten": "B. Phiếu khám / đánh giá chuyên khoa", "block": [{"ma": "nt_ly_do", "ten": "Lý do khám bệnh", "kieu": "doan_van", "nhom": "1. Lý do khám bệnh"}, {"ma": "nt_para", "ten": "PARA", "kieu": "text", "nhom": "2. Tiền sử phụ khoa và sản khoa", "thu_gon": true}, {"ma": "nt_menarche", "ten": "Tuổi lần đầu thấy kinh", "kieu": "so", "nhom": "2. Tiền sử phụ khoa và sản khoa", "thu_gon": true}, {"ma": "nt_cycle", "ten": "Chu kỳ kinh nguyệt (ngày)", "kieu": "so", "nhom": "2. Tiền sử phụ khoa và sản khoa", "thu_gon": true}, {"ma": "nt_marriage_age", "ten": "Tuổi lấy chồng", "kieu": "so", "nhom": "2. Tiền sử phụ khoa và sản khoa", "thu_gon": true}, {"ma": "nt_contraception", "ten": "Biện pháp tránh thai đang dùng", "kieu": "text", "nhom": "2. Tiền sử phụ khoa và sản khoa", "thu_gon": true}, {"ma": "nt_gyn_disease", "ten": "Các bệnh phụ khoa đang điều trị", "kieu": "doan_van", "nhom": "2. Tiền sử phụ khoa và sản khoa", "thu_gon": true}, {"ma": "nt_gyn_surgery", "ten": "Phẫu thuật phụ khoa", "kieu": "doan_van", "nhom": "2. Tiền sử phụ khoa và sản khoa", "thu_gon": true}, {"ma": "nt_endo_hist", "ten": "3. Tiền sử nội tiết", "kieu": "nhieu_chon", "lua_chon": [{"ma": "nt_endo_hist_1", "ten": "Đái tháo đường"}, {"ma": "nt_endo_hist_2", "ten": "Tuyến giáp"}, {"ma": "nt_endo_hist_3", "ten": "Tuyến thượng thận"}, {"ma": "nt_endo_hist_4", "ten": "PCOS"}, {"ma": "nt_endo_hist