", "nhom": "Lối sống - Dinh dưỡng - Vận động"}, {"ma": "nt_lifestyle_activity", "ten": "Vận động", "kieu": "doan_van", "nhom": "Lối sống - Dinh dưỡng - Vận động"}, {"ma": "nt_lifestyle_other", "ten": "Giảm cân / thuốc lá / rượu bia / giấc ngủ", "kieu": "doan_van", "nhom": "Lối sống - Dinh dưỡng - Vận động"}]}, {"ma": "E", "ten": "E. Chỉ định điều trị", "block": [{"ma": "nt_treatment_other", "ten": "Điều trị khác / thuốc ngoài danh mục", "kieu": "doan_van", "goi_y": "Nhập tự do nếu chưa có trong danh mục", "khoa_tu": "name"}, {"ma": "nt_treatment_note", "ten": "Lời dặn điều trị chung", "kieu": "doan_van", "goi_y": "Lời dặn chung cho bệnh nhân", "khoa_tu": "name"}], "lien_ket": {"loai": "don_thuoc", "rang_buoc": "prescription.drug_catalog_id"}}, {"ma": "F", "ten": "F. Chỉ định thủ thuật", "block": [], "lien_ket": {"loai": "chi_dinh_thu_thuat", "rang_buoc": "service_order_id"}}, {"ma": "G", "ten": "G. Theo dõi và tái khám", "block": [{"ma": "nt_follow_date", "ten": "Ngày tái khám", "kieu": "ngay"}, {"ma": "nt_follow_tests", "ten": "Cần kiểm tra lại khi tái khám", "kieu": "nhieu_chon", "lua_chon": [{"ma": "nt_follow_tests_1", "ten": "Hormone"}, {"ma": "nt_follow_tests_2", "ten": "Sinh hóa"}, {"ma": "nt_follow_tests_3", "ten": "Siêu âm"}, {"ma": "nt_follow_tests_4", "ten": "DXA"}, {"ma": "nt_follow_tests_5", "ten": "Pap smear"}], "ten_tu_dat": true}, {"ma": "nt_follow_note", "ten": "Ghi chú theo dõi", "kieu": "doan_van"}]}]$khung$::jsonb
), doi AS (
    UPDATE public.form_definition d SET trang_thai = 'RETIRED'
      FROM cu WHERE d.clinic_id = cu.clinic_id AND d.form_id = 'NT'
       AND d.version = cu.version
    RETURNING d.clinic_id
)
INSERT INTO public.form_definition
    (clinic_id, form_id, version, ten, nhom, khung, trang_thai,
     xuat_ban_boi, xuat_ban_luc)
SELECT cu.clinic_id, 'NT',
