), doi AS (
    UPDATE public.form_definition d SET trang_thai = 'RETIRED'
      FROM cu WHERE d.clinic_id = cu.clinic_id AND d.form_id = 'NK'
       AND d.version = cu.version
    RETURNING d.clinic_id
)
